// Decade counter: counts 1, 2, ..., 10 in a "decade" (i.e., one
// register cascade, with a separate register to increment the
// "decade" counter).
module TopModule(input  clk, input reset, output [3:0] q);
  reg [3:0] count;
  reg [1:0] decade;
  always @(posedge clk) begin
    if (reset) begin
      count <= 4'd1;
      decade <= 2'd0;
    end else begin
      if (count == 4'd10) begin
        count <= 4'd1;
        decade <= decade + 2'd1;
      end else begin
        count <= count + 4'd1;
      end
    end
  end
  assign q = {decade, count};
endmodule

